        "question": "割り勘は、冷たい印象を与えませんか？",
        "answer": "割り勘は、対等な関係を大切にする考え方の一つです。「半分ずつにしよう」と、前向きな言葉で伝えると、気持ちよく受け取ってもらいやすくなります。"
