        "question": "復縁の連絡は、どのくらい期間を空けるのがよいですか？",
        "answer": "別れ方や二人の状況によって異なりますが、お互いの気持ちが落ち着くまで、数週間〜数か月ほど期間を空けるケースが多いです。焦らず、自分の気持ちが整ってから動きましょう。"
