    "content": "<h2 id=\"section-1\">1. 干合（かんごう）とは？陰陽五行が惹き合う運命の磁石</h2>\n<p>四柱推命において、十干のうち特定の「陽干」と「陰干」が結びつく特別な組み合わせを<strong>「干合（かんごう）」</strong>と呼びます。</p>\n<p>磁石のS極とN極のように強烈に引き合い、出会った瞬間に「昔から知っていたような懐かしさ」「強烈な一目惚れ」を感じるのが特徴です。</p>\n<h2 id=\"section-2\">2. 【5大干合ペア別】惹かれ合うメカニズムと関係性の特徴</h2>\n<h3>① 甲（大樹）× 己（田畑）：中正の合</h3>\n<p>誠実で穏やかな信頼関係。お互いを深く尊重し、地に足のついた温かい家庭を築きます。</p>\n<h3>② 乙（草花）× 庚（鉱石）：仁義の合</h3>\n<p>庚の逞しい決断力と乙の柔軟な優しさが絶妙に噛み合う、理想的な役割分担カップルです。</p>\n<h3>③ 丙（太陽）× 辛（宝石）：威制の合</h3>\n<p>情熱的な輝きと洗練された美意識がスパークする、ドラマティックで華やかな恋情を生み出します。</p>\n<h3>④ 丁（月・灯火）× 壬（大河）：淫佚の合（情愛の合）</h3>\n<p>理性を超えた強烈な性的引力と深いロマンス。魂の底から求め合う濃厚な絆を結びます。</p>\n<h3>⑤ 戊（大山）× 癸（雨露）：無情の合（変革の合）</h3>\n<p>包容力のある戊と繊細な癸。お互いの価値観を刺激し合い、人生を大きく好転させるパートナーシップです。</p>\n<h2 id=\"section-3\">3. 日干同士が干合する相手と出会った時に起きるサイン</h2>\n<p>共通の偶然が重なる、相手の匂いや声に強い安心感を覚えるなど、潜在意識レベルでの共鳴が起こります。</p>\n<h2 id=\"section-4\">4. まとめ＆あなたとお相手の干合を診断する</h2>\n<p>『月と蓮』の本格鑑定で、あなたと好きな人の日干干合関係を今すぐ無料チェックしてみましょう。</p>"
